CLocalMatchmaker mm;
auto a = mm.StartSearch("ranked_1v1", 1500);  // プレイヤーA が検索
auto b = mm.StartSearch("ranked_1v1", 1480);  // プレイヤーB が検索 → 互いに発見
if (mm.PollStatus(a.Value()) == acs::game::EMatchStatus::Matched) {
    mm.AcceptMatch(a.Value());                 // 双方が Accept で確定
}
